ALTER TABLE public.alerts ADD CONSTRAINT alerts_status_fields_check CHECK ((status = 'OPEN' AND acknowledged_at IS NULL AND acknowledged_by IS NULL AND resolved_at IS NULL AND resolved_by IS NULL AND resolution_notes IS NULL) OR (status = 'ACKNOWLEDGED' AND acknowledged_at IS NOT NULL AND acknowledged_by IS NOT NULL AND resolved_at IS NULL AND resolved_by IS NULL AND resolution_notes IS NULL) OR (status = 'RESOLVED' AND acknowledged_at IS NOT NULL AND acknowledged_by IS NOT NULL AND resolved_at IS NOT NULL AND resolved_by IS NOT NULL AND length(btrim(resolution_notes)) > 0));